var i=`0645-yassa-poulet`;var t=`world-0645`;var s=`SN`;var a=`western-africa`;var o=4;var r=170;var l={en:`Yassa Poulet`,ua:`Курка яса`};var h={en:`Yassa Poulet is a Senegal classic prepared with chicken thigh, yellow onion, lemon juice, dijon mustard. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Курка яса, страва кухні країни Сенегал зі складниками: куряче стегно, жовта цибуля, лимонний сік, діжонська гірчиця. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var c=[{en:`Rub chicken thoroughly with sliced onions, fresh lemon juice, mustard and garlic; marinate under refrigeration, then reserve the onions.`,ua:`Натріть курку нарізаною цибулею, лимонним соком, гірчицею й часником; маринуйте в холодильнику, потім відкладіть цибулю.`,t:[`marinating`],m:120,i:[[`chicken-thigh`,850,`g`],[`yellow-onion`,440,`g`],[`lemon-juice`,130,`ml`],[`dijon-mustard`,28,`g`],[`garlic`,5,`clove`],[`table-salt`,null,`to_taste`]]},{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`sunflower-oil`,55,`ml`]]},{en:`Slowly soften the reserved marinated onions, then braise browned chicken in the tangy sauce until fully cooked.`,ua:`Повільно розм’якшіть мариновану цибулю й тушкуйте підрум’янену курку в кислуватому соусі до повної готовності.`,t:[`braising`],m:35,i:[[`chicken-stock`,240,`ml`],[`bay-leaf`,2,`leaf`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,18,`g`]]}];var u={slug:i,id:t,country:`SN`,region:a,servings:4,minutes:170,title:l,text:h,steps:c};export{s as country,u as default,t as id,r as minutes,a as region,o as servings,i as slug,c as steps,h as text,l as title};